# characterize masked orbits fully unknown
orbits={}
for i,j in missing:
 key=tuple(sorted({(i,j),(23-i,j),(i,23-j),(23-i,23-j)}))
 orbits[key]=[grid[a][b] for a,b in key]
[(k,v) for k,v in orbits.items() if all(x==2 for x in v)]

transforms=lambda i,j: {(i,j),(23-i,j),(i,23-j),(23-i,23-j),(j,i),(23-j,i),(j,23-i),(23-j,23-i)}
unknown_orbits=[]
for i,j in missing:
 vals=[grid[a][b] for a,b in transforms(i,j)]
 if all(v==2 for v in vals): unknown_orbits.append((i,j,transforms(i,j)))
len(unknown_orbits), unknown_orbits[:3]

out=[row.copy() for row in grid]
conflicts=[]
for i,j in missing:
 vals={grid[a][b] for a,b in transforms(i,j) if grid[a][b]!=2}
 if len(vals)!=1: conflicts.append((i,j,vals))
 else: out[i][j]=vals.pop()
len(conflicts),len(missing),[' '.join(map(str,r)) for r in out]
